# Replace orchestrator.py completely with clean, fixed version
cat > ~/termux-multi-agent/src/orchestrator.py << 'PYEOF'
import sys, os, re, json, subprocess
from pathlib import Path
from datetime import datetime
import logging

sys.path.insert(0, "/data/data/com.termux/files/home/deepcli")
from deepcli.core import get_token, create_session, chat_completion, fetch_sessions

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] [%(name)s]: %(message)s")
logger = logging.getLogger("orchestrator")

class TermuxAgentOrchestrator:
    def __init__(self, workspace_root: str):
        self.workspace = Path(workspace_root)
        self.token = get_token()
        self.session_id = None
        self._init_session()

    def _init_session(self):
        try:
            self.session_id = create_session(self.token, "expert")
            logger.info(f"Agent session created: {self.session_id}")
        except Exception as e:
            logger.warning(f"Session creation failed: {e}, will use stateless fallback")

    def call_deepseek_v4_pro(self, system_prompt: str, user_prompt: str) -> str:
        full_prompt = f"System: {system_prompt}\n\nUser: {user_prompt}"
        if self.session_id:
            try:
                return chat_completion(self.token, full_prompt, self.session_id, model_type="expert")
            except Exception as e:
                logger.warning(f"Completion failed, retrying with new session: {e}")
                self._init_session()
        return chat_completion(self.token, full_prompt, self.session_id, model_type="expert")

    def parse_and_apply_cedar_diff(self, target_file, coder_output):
        logger.debug(f"LLM raw output (first 500 chars): {coder_output[:500]}")
        code_blocks = re.findall(r"```[^`]*```", coder_output, re.DOTALL)
        if not code_blocks:
            if any(line.strip().startswith(('def ', 'class ', 'import ', 'from ')) for line in coder_output.splitlines()):
                code_blocks = [coder_output]
            else:
                return False, "No code block found in LLM output"
        block = code_blocks[0]
        block = re.sub(r'^```[^\n]*\n', '', block)
        block = re.sub(r'\n?```$', '', block)
        Path(target_file).write_text(block)
        return True, f"Applied patch to {target_file}"

    def run_refactor_pipeline(self, target_file, language="python", request_instruction=None, test_command=None):
        logger.info("Initializing isolated branch...")
        target_path = Path(target_file)
        if not target_path.exists():
            logger.error(f"Target file missing: {target_file}")
            return

        original = target_path.read_text()
        funcs = []
        try:
            ast_result = subprocess.check_output(
                ["ast-grep", "run", "--pattern", "def $_FUNC($$$ARGS): { $$$BODY }", "--lang", language, "--json", str(target_path)],
                cwd=str(self.workspace), text=True, stderr=subprocess.DEVNULL
            )
            if ast_result.strip():
                for m in json.loads(ast_result):
                    funcs.append(m.get("metaVariables", {}).get("FUNC", "unknown"))
        except Exception:
            pass

        coder_system = "You are a l33T code refactoring assistant. Reply with only the improved code in a single code block."
        instr = request_instruction or "Refactor this code to improve performance and readability"
        user_prompt = f"File: {target_file}\nFunctions: {funcs}\n{instr}\n```\n{original}\n```"

        for attempt in range(3):
            logger.info(f"(try {attempt+1}): Generating code fix...")
            coder_output = self.call_deepseek_v4_pro(coder_system, user_prompt)
            success, msg = self.parse_and_apply_cedar_diff(target_file, coder_output)
            if success:
                logger.info(f"Refactor succeeded: {msg}")
                return
            logger.warning(f"Attempt {attempt+1} failed: {msg}")
        logger.error("All refactor attempts exhausted")

    def search_conversations(self, term: str):
        sessions = fetch_sessions(self.token)
        results = []
        for s in sessions:
            title = s.get("title", "") or s.get("name", "")
            if term.lower() in title.lower():
                results.append(s)
        return results
PYEOF
echo "[+] orchestrator.py completely rewritten and clean"
