    version_ptr = Pointer(s['id'], 0, 0, version)  # version hash as content_hash
    idx.taxonomy.add_pointer(version_ptr, ['_versions', dag.title[:40], version[:8]])
    idx.blobs[version] = str(repo_dir / 'HEAD.json')
    print(f"Versioned: {dag.title[:50]} → {version[:12]}")
idx._save()
