#!/usr/bin/env node
/*
Lightweight HTTP/HTTPS proxy for capturing request headers.
Usage: node http_sniffer.js [port]
*/
const http = require('http');
const net = require('net');
const PORT = process.argv[2] || 8888;

const server = http.createServer((req, res) => {
  console.log(`\n=== ${req.method} ${req.url} ===`);
  for (const [k,v] of Object.entries(req.headers)) {
    if (k.includes('client') || k.includes('app') || k.includes('version') || k.includes('auth') || k.includes('expert')) {
      console.log(`  ${k}: ${v}`);
    }
  }
  res.writeHead(200, {'Content-Type': 'text/plain'});
  res.end('OK');
});

server.on('connect', (req, clientSocket, head) => {
  const [host, port] = req.url.split(':');
  const serverSocket = net.connect(port || 443, host, () => {
    clientSocket.write('HTTP/1.1 200 Connection Established\r\n\r\n');
    serverSocket.write(head);
    serverSocket.pipe(clientSocket);
    clientSocket.pipe(serverSocket);
  });
  serverSocket.on('error', () => clientSocket.end());
});

server.listen(PORT, () => console.log(`Sniffer on :${PORT} — set browser proxy to localhost:${PORT}`));
EOF
