### 4. Fix dangling detection: use the DAG repo data

```bash
python3 << 'EOF'
import json, sys
from pathlib import Path
from collections import deque

HOME = Path.home()
REPO = HOME / 'cli-synthegration' / 'repo'

print("=== Dangling Branches from DAG Repository ===\n")
total_dangling = 0

for session_dir in sorted(REPO.iterdir()):
    if not session_dir.is_dir():
        continue
    head_file = session_dir / 'HEAD.json'
    if not head_file.exists():
        continue

    try:
        head = json.loads(head_file.read_text())
    except:
        continue

    edges = head.get('edges', {})
    nodes = head.get('nodes', [])
    id_to_hash = head.get('id_to_hash', {})
    roots = head.get('roots', [])
    title = head.get('title', session_dir.name)

    # Build children map
    children = {h: [] for h in nodes}
    for parent, kids in edges.items():
        if parent in children:
            children[parent].extend(kids)

    # Find nodes with siblings but no children (dangling)
    for h in nodes:
        # Find parent by searching edges
        parent = None
        for p, kids in edges.items():
            if h in kids:
                parent = p
                break

        if not parent:
            continue

        siblings = children.get(parent, [])
        my_children = children.get(h, [])

        if len(siblings) >= 2 and len(my_children) == 0:
            total_dangling += 1
            print(f"Session: {title[:60]}")
            print(f"  Dangling node hash: {h[:12]}...")
            print(f"  Parent: {parent[:12]}..., Siblings: {len(siblings)}")
            # Try to get snippet from blob
            blob = session_dir / 'objects' / f'{h}.json'
            if blob.exists():
                obj = json.loads(blob.read_text())
                print(f"  Role: {obj.get('role','unknown')}")
            print()

print(f"Total dangling branches across all DAGs: {total_dangling}")
EOF
