### 3. Dangling forks: relaxed scan with full visibility

```bash
python3 << 'EOF'
import sys
sys.path.insert(0, '/data/data/com.termux/files/home/deepcli')
from deepcli.core import get_token, fetch_sessions, get_history

token = get_token()
sessions = fetch_sessions(token)
print(f"Scanning {len(sessions)} sessions for fork points...\n")

for s in sessions[:40]:
    try:
        msgs = get_history(token, s['id'])
        if not msgs or len(msgs) < 3:
            continue
    except:
        continue

    # Build tree
    tree = {}
    for m in msgs:
        mid = m.get('id','')
        pid = m.get('parent_id')
        tree[mid] = {'pid': pid, 'role': m.get('role',''), 'kids': [], 'ts': m.get('inserted_at','')}
    for mid, node in tree.items():
        p = node['pid']
        if p and p in tree:
            tree[p]['kids'].append(mid)

    # Find nodes with 2+ children (fork points)
    forks = [(mid, node) for mid, node in tree.items() if len(node['kids']) >= 2]
    if forks:
        title = s.get('title','')[:60]
        print(f"Session: {title}")
        for mid, node in forks:
            kids = node['kids']
            # Count how many children have further responses vs dangling
            continued = sum(1 for k in kids if k in tree and len(tree[k]['kids']) > 0)
            abandoned = len(kids) - continued
            print(f"  Fork at {mid[:8]}... ({len(kids)} branches: {continued} continued, {abandoned} dangling)")
            for k in kids:
                k_node = tree.get(k, {})
                has_kids = len(k_node.get('kids', []))
                role = k_node.get('role', '?')
                ts = k_node.get('ts', '')[:10]
                marker = '🌿→' if has_kids > 0 else '🍂✗'
                print(f"    {marker} {k[:8]}... ({role}, {ts})")
        print()
