# 1. Proper HTTPS‑intercepting proxy (handles CONNECT tunnels)
kill %1 %2 2>/dev/null
cat > ~/cli-synthegration/http_sniffer.js << 'JSEOF'
const http = require('http');
const net = require('net');
const fs = require('fs');
const PORT = process.argv[2] || 8888;
const LOG = process.argv[3] || (__dirname + '/sniffer_capture.log');

function log(msg) {
    console.log(msg);
    fs.appendFileSync(LOG, msg + '\n');
}

// HTTP requests (plain)
const server = http.createServer((req, res) => {
    let body = [];
    req.on('data', chunk => body.push(chunk));
    req.on('end', () => {
        log(`\n=== ${req.method} ${req.url} ===`);
        for (const [k,v] of Object.entries(req.headers)) {
            if (/client|app|version|auth|expert|content|cookie|x-ds|pow/i.test(k))
                log(`  ${k}: ${v}`);
        }
        const full = Buffer.concat(body).toString();
        if (full && full.length < 5000) log(`  BODY: ${full.slice(0,2000)}`);
        res.writeHead(200, {'Content-Type': 'text/plain'});
        res.end('OK');
    });
});

// CONNECT tunnel (HTTPS) — intercept and forward, logging the initial CONNECT
server.on('connect', (req, clientSocket, head) => {
    const [host, port] = req.url.split(':');
    log(`\n=== CONNECT ${host}:${port} ===`);
    const serverSocket = net.connect(port || 443, host, () => {
        clientSocket.write('HTTP/1.1 200 Connection Established\r\n\r\n');
        serverSocket.write(head);
        serverSocket.pipe(clientSocket);
        clientSocket.pipe(serverSocket);
    });
    serverSocket.on('error', (e) => {
        log(`  CONNECT error: ${e.message}`);
        clientSocket.end();
    });
    clientSocket.on('error', () => serverSocket.end());
});

server.listen(PORT, '127.0.0.1', () => log(`Sniffer on 127.0.0.1:${PORT} → ${LOG}`));
JSEOF
node ~/cli-synthegration/http_sniffer.js 8888 &
sleep 1
echo "Sniffer restarted on 127.0.0.1:8888 — edit a message in Firefox now"
